-- Nur Finance dataset — PostgreSQL. Generated by scripts/make_dataset.py (seed 20261016).
-- 1) Run the CREATE TABLE block. 2) Load each CSV from data/raw/ with the loader shown at the bottom.

CREATE TABLE branches (
  branch_id BIGINT,
  branch_name VARCHAR(100),
  region VARCHAR(100),
  opened_on DATE
);

CREATE TABLE products (
  product_id BIGINT,
  code VARCHAR(100),
  name VARCHAR(100),
  min_amount BIGINT,
  max_amount BIGINT,
  annual_rate DECIMAL(10,4),
  channel VARCHAR(100)
);

CREATE TABLE staff (
  staff_id BIGINT,
  branch_id BIGINT,
  role VARCHAR(100),
  full_name VARCHAR(100),
  hired_on DATE
);

CREATE TABLE customers (
  customer_id BIGINT,
  first_name VARCHAR(100),
  last_name VARCHAR(100),
  sex VARCHAR(100),
  birth_date DATE,
  region VARCHAR(100),
  segment VARCHAR(100),
  income_source VARCHAR(100),
  monthly_income BIGINT,
  phone VARCHAR(100),
  registered_at DATE
);

CREATE TABLE applications (
  application_id BIGINT,
  customer_id BIGINT,
  product_id BIGINT,
  branch_id BIGINT,
  channel VARCHAR(100),
  applied_at TIMESTAMP,
  requested_amount BIGINT,
  term_months BIGINT,
  credit_score BIGINT,
  status VARCHAR(100),
  decided_at DATE,
  officer_id BIGINT
);

CREATE TABLE loans (
  loan_id BIGINT,
  application_id BIGINT,
  customer_id BIGINT,
  product_id BIGINT,
  branch_id BIGINT,
  disbursed_at DATE,
  principal BIGINT,
  term_months BIGINT,
  annual_rate DECIMAL(10,4),
  monthly_payment BIGINT,
  risk_grade VARCHAR(100),
  status VARCHAR(100),
  closed_at DATE
);

CREATE TABLE installments (
  installment_id BIGINT,
  loan_id BIGINT,
  installment_no BIGINT,
  due_date DATE,
  principal_due BIGINT,
  interest_due BIGINT,
  total_due BIGINT
);

CREATE TABLE payments (
  payment_id BIGINT,
  loan_id BIGINT,
  installment_id BIGINT,
  paid_at DATE,
  amount BIGINT,
  method VARCHAR(100)
);

CREATE TABLE collections_actions (
  action_id BIGINT,
  loan_id BIGINT,
  action_date DATE,
  action_type VARCHAR(100),
  collector_id BIGINT,
  outcome VARCHAR(100)
);

CREATE TABLE app_events (
  event_id BIGINT,
  customer_id BIGINT,
  event_name VARCHAR(100),
  event_time TIMESTAMP,
  application_id BIGINT,
  device VARCHAR(100),
  app_version VARCHAR(100)
);

CREATE TABLE dim_date (
  date_key DATE,
  year BIGINT,
  quarter BIGINT,
  month BIGINT,
  month_name VARCHAR(100),
  day BIGINT,
  weekday VARCHAR(100),
  is_weekend BIGINT
);

-- Loaders
\copy branches FROM 'data/raw/branches.csv' WITH (FORMAT csv, HEADER true, NULL '');
\copy products FROM 'data/raw/products.csv' WITH (FORMAT csv, HEADER true, NULL '');
\copy staff FROM 'data/raw/staff.csv' WITH (FORMAT csv, HEADER true, NULL '');
\copy customers FROM 'data/raw/customers.csv' WITH (FORMAT csv, HEADER true, NULL '');
\copy applications FROM 'data/raw/applications.csv' WITH (FORMAT csv, HEADER true, NULL '');
\copy loans FROM 'data/raw/loans.csv' WITH (FORMAT csv, HEADER true, NULL '');
\copy installments FROM 'data/raw/installments.csv' WITH (FORMAT csv, HEADER true, NULL '');
\copy payments FROM 'data/raw/payments.csv' WITH (FORMAT csv, HEADER true, NULL '');
\copy collections_actions FROM 'data/raw/collections_actions.csv' WITH (FORMAT csv, HEADER true, NULL '');
\copy app_events FROM 'data/raw/app_events.csv' WITH (FORMAT csv, HEADER true, NULL '');
\copy dim_date FROM 'data/raw/dim_date.csv' WITH (FORMAT csv, HEADER true, NULL '');
